import { NO_COPY_CLASS } from "@hunt/copy-to-clipboard";
import { Button } from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import { parse as parseEmoji } from "@twemoji/parser";
import React, {
  useState,
  useEffect,
  useMemo,
  useCallback,
  useRef,
} from "react";
import { Md5 } from "ts-md5";
import { computeExtractionResult } from "./extractionData";
import type {
  Field,
  Blank,
  LayerPuzzle,
  ExtractionDataResponse,
} from "./types";

const getExtractionChangeMessage = (hasExtraction: boolean) =>
  `Extraction data has been ${hasExtraction ? "added" : "removed"}`;

const getValidationMessageForPuzzle = (idx: number, correct: boolean) =>
  `Puzzle ${idx + 1} is ${correct ? "correct" : "incorrect"}.`;

type ExportedState = {
  puzzleId: string;
  inputs: Record<string, string>;
};

type ReadyMicropuzzle = {
  key: string;
  puzzleIdx: number;
  micropuzzleData: string[];
};

// ### FieldComponent ###
// Updated to accept extractionInfo
type FieldComponentProps = {
  fields: Field;
  extractionInfo: Record<string, number> | undefined;
  inputHandler: (
    e: React.ChangeEvent<HTMLInputElement>,
    charId: string,
  ) => void;
  focusHandler: (e: React.FocusEvent<HTMLInputElement>) => void;
  keyDownHandler: (
    e: React.KeyboardEvent<HTMLInputElement>,
    charId: string,
  ) => void;
  inputs: Record<string, string>;
};

type GroupItem =
  | { type: "input-group"; items: Blank[] }
  | { type: "separator"; item: Blank };

const FieldComponent: React.FC<FieldComponentProps> = ({
  fields,
  extractionInfo,
  inputHandler,
  focusHandler,
  keyDownHandler,
  inputs,
}) => {
  const groupItems = (items: Blank[]): GroupItem[] => {
    // Group consecutive items with non-zero charId together
    const groups: GroupItem[] = [];
    let currentGroup: Blank[] = [];

    for (const item of items) {
      if (!item.given) {
        currentGroup.push(item);
      } else {
        if (currentGroup.length > 0) {
          groups.push({ type: "input-group", items: currentGroup });
          currentGroup = [];
        }
        groups.push({ type: "separator", item: item });
      }
    }

    if (currentGroup.length > 0) {
      groups.push({ type: "input-group", items: currentGroup });
    }

    return groups;
  };

  let extractionIndex = 0;
  return (
    <div style={{ display: "flex", flexWrap: "wrap" }}>
      {fields.given ? (
        <div style={{ height: 46, fontSize: 30 }}>{fields.data}</div>
      ) : (
        groupItems(fields.data).map((group, groupIdx) => {
          if (group.type === "input-group") {
            return (
              <div
                key={groupIdx}
                style={{ display: "flex", whiteSpace: "nowrap" }}
              >
                {group.items.map((item, itemIdx) => {
                  // Given items have id: null, so use itemIdx as fallback
                  const inputKey = item.given ? String(itemIdx) : item.id;

                  const extractionId =
                    extractionInfo === undefined
                      ? undefined
                      : extractionInfo[extractionIndex++];

                  return (
                    <div
                      key={itemIdx}
                      style={{ display: "inline-block", textAlign: "center" }}
                    >
                      <input
                        data-blank-input="true"
                        data-char-id={inputKey}
                        style={{
                          width: 28,
                          height: 28,
                          fontSize: 16,
                          textAlign: "center",
                          outlineOffset: -3,
                          border: extractionId ? "2px solid red" : undefined,
                        }}
                        type="text"
                        maxLength={1}
                        value={inputs[inputKey] || ""}
                        onChange={(e) => {
                          inputHandler(e, inputKey);
                        }}
                        onFocus={focusHandler}
                        onKeyDown={(e) => {
                          keyDownHandler(e, inputKey);
                        }}
                        placeholder={
                          item.linked ? String(item.displayedId) : "_"
                        }
                      />
                      <div
                        style={{
                          height: 16,
                          fontSize: 16,
                          color: "red",
                          marginBottom: 8,
                        }}
                      >
                        {extractionId || ""}
                      </div>
                    </div>
                  );
                })}
              </div>
            );
          } else {
            // This is a 'GivenBlank' (separator)
            return (
              <div
                key={groupIdx}
                style={{ display: "inline-block", textAlign: "center" }}
              >
                <span
                  style={{ display: "inline-block", width: 30, height: 30 }}
                >
                  {
                    // Use non-breaking space (\u00A0) to ensure space characters are visible in the UI,
                    // as regular spaces may collapse or be ignored in HTML rendering.
                    group.item.displayedChar === " "
                      ? "\u00A0"
                      : group.item.displayedChar
                  }
                </span>
                <div
                  style={{
                    height: 16,
                    fontSize: 16,
                    color: "red",
                    marginBottom: 8,
                  }}
                ></div>
              </div>
            );
          }
        })
      )}
    </div>
  );
};

// ### PuzzleComponent ###

type PuzzleComponentProps = {
  id: string;
  data: LayerPuzzle;
  checkSlug?: string;
};

const PuzzleComponent: React.FC<PuzzleComponentProps> = ({
  id,
  data,
  checkSlug = "layers",
}) => {
  const [inputs, setInputs] = useState<Record<string, string>>({});

  // Aria label for the puzzle overall.
  const [overallPuzzleAria, setOverallPuzzleAria] = useState<string>();

  // Aria labels for each individual puzzle (label for puzzle i is ariaLabels[i]).
  const [ariaLabels, setAriaLabels] = useState<string[]>(
    new Array(data.length).fill(""),
  );

  const [extractionInfo, setExtractionInfo] = useState<
    Record<number, number>[][]
  >([]);

  const [verifiedPuzzles, setVerifiedPuzzles] = useState<Set<number>>(
    new Set(),
  );

  // State to track failed inputs (correct hash, wrong answer)
  const [failedInputs, setFailedInputs] = useState<Record<number, string>>({});

  const pendingChecksRef = useRef<Set<number>>(new Set());
  const [pendingChecks, setPendingChecks] = useState<Set<number>>(new Set());
  const readyMicropuzzleRef = useRef<ReadyMicropuzzle>();
  const extractionCacheRef = useRef<Map<string, ExtractionDataResponse>>(
    new Map(),
  );

  const circledNumbers = "①②③④⑤⑥⑦⑧⑨⑩⑪";

  // Memoize the list of blank IDs for each puzzle
  // Returns a map: { puzzleIdx: ["id1", "id2", ...] }
  const puzzleBlankIds = useMemo(() => {
    const idMap: Record<number, string[]> = {};
    data.forEach((puzzle, puzzleIdx) => {
      const ids: string[] = [];

      // Get IDs from title
      if (!puzzle.title.given) {
        puzzle.title.data.forEach((blank) => {
          if (!blank.given) ids.push(blank.id);
        });
      }
      // Get IDs from fields
      puzzle.fields.forEach((field) => {
        if (!field.given) {
          field.data.forEach((blank) => {
            if (!blank.given) ids.push(blank.id);
          });
        }
      });
      idMap[puzzleIdx] = ids;
    });
    return idMap;
  }, [data]);

  // Load from localStorage
  useEffect(() => {
    const saveKey = `layers-answers-${id}`;
    const savedInputs = localStorage.getItem(saveKey);
    if (savedInputs) {
      try {
        const input = JSON.parse(savedInputs) as Record<string, string>;
        setInputs(input);
      } catch (e) {
        console.error("Failed to load saved inputs:", e);
      }
    }
  }, [id]);

  // Save to localStorage
  useEffect(() => {
    const saveKey = `layers-answers-${id}`;
    localStorage.setItem(saveKey, JSON.stringify(inputs));
  }, [id, inputs]);

  // <-- ADDED: Helper to get content string for any puzzle idx -->
  const getMicropuzzleContentString = useCallback(
    (puzzleIdx: number): string => {
      const ids = puzzleBlankIds[puzzleIdx];
      if (!ids) return "";
      // Get the input for each id, or "" if it's empty/undefined
      return ids.map((id) => inputs[id] || "").join("");
    },
    [inputs, puzzleBlankIds],
  );

  const unverifyPuzzle = useCallback((puzzleIdx: number) => {
    let removed = false;
    setVerifiedPuzzles((prev) => {
      if (!prev.has(puzzleIdx)) {
        return prev;
      }
      removed = true;
      const res = new Set(prev);
      res.delete(puzzleIdx);
      return res;
    });

    if (!removed) {
      return;
    }

    setExtractionInfo((_) => []);
    setAriaLabels((prev) => {
      const res = [...prev];
      const newMessage = getValidationMessageForPuzzle(puzzleIdx, false);
      res[puzzleIdx] = newMessage;
      return res;
    });
    setOverallPuzzleAria((prev) => {
      const newMessage = getExtractionChangeMessage(false);
      if (prev === "" || prev === undefined) {
        return prev;
      }
      return newMessage;
    });
  }, []);

  const applyExtractionResult = useCallback(
    (
      puzzleIdx: number,
      micropuzzleData: string[],
      result: ExtractionDataResponse,
    ) => {
      if (!result.isCorrect) {
        setFailedInputs((prev) => ({
          ...prev,
          [puzzleIdx]: micropuzzleData[puzzleIdx],
        }));

        unverifyPuzzle(puzzleIdx);
        return;
      }

      setExtractionInfo((_) => result.extractionData);
      setOverallPuzzleAria((prev) => {
        const hasExtraction = result.extractionData.length !== 0;
        if (prev !== "" && prev !== undefined) {
          return getExtractionChangeMessage(hasExtraction);
        } else if (hasExtraction) {
          return getExtractionChangeMessage(true);
        }
        return prev;
      });

      setVerifiedPuzzles((prev) => new Set(prev).add(puzzleIdx));
      setAriaLabels((prev) => {
        const res = [...prev];
        res[puzzleIdx] = getValidationMessageForPuzzle(puzzleIdx, true);
        return res;
      });
    },
    [unverifyPuzzle],
  );

  const fetchExtractionInfo = useCallback(
    (puzzleIdx: number, micropuzzleData: string[]) => {
      const cacheKey = `${id}:${checkSlug}:${puzzleIdx}:${JSON.stringify(
        micropuzzleData,
      )}`;

      const cached = extractionCacheRef.current.get(cacheKey);
      if (cached) {
        applyExtractionResult(puzzleIdx, micropuzzleData, cached);
        return;
      }

      if (pendingChecksRef.current.has(puzzleIdx)) {
        return;
      }
      pendingChecksRef.current.add(puzzleIdx);
      setPendingChecks(new Set(pendingChecksRef.current));

      const result: ExtractionDataResponse = computeExtractionResult(
        id,
        puzzleIdx,
        micropuzzleData,
      );
      extractionCacheRef.current.set(cacheKey, result);
      applyExtractionResult(puzzleIdx, micropuzzleData, result);

      pendingChecksRef.current.delete(puzzleIdx);
      setPendingChecks(new Set(pendingChecksRef.current));
    },
    [applyExtractionResult, checkSlug, id],
  );

  const readyMicropuzzle = useMemo<ReadyMicropuzzle | undefined>(() => {
    for (const puzzleIdxStr in puzzleBlankIds) {
      const puzzleIdx = Number(puzzleIdxStr);
      const ids = puzzleBlankIds[puzzleIdx];
      if (!ids?.length) {
        continue;
      }

      const allFilled = ids.every(
        (id) => inputs[id] && inputs[id].trim() !== "",
      );
      if (!allFilled) {
        continue;
      }

      if (verifiedPuzzles.has(puzzleIdx)) {
        continue;
      }

      const inputString = ids.map((id) => inputs[id] || "").join("");
      if (failedInputs[puzzleIdx] === inputString) {
        continue;
      }

      const expectedHash = data[puzzleIdx]?.expectedHash;
      if (!expectedHash) {
        continue;
      }

      const hash = Md5.hashStr(inputString);
      if (hash !== expectedHash) {
        continue;
      }

      const micropuzzleData = data.map((_, idx) =>
        getMicropuzzleContentString(idx),
      );

      return {
        key: `${puzzleIdx}:${inputString}`,
        puzzleIdx,
        micropuzzleData,
      };
    }

    return undefined;
  }, [
    data,
    failedInputs,
    getMicropuzzleContentString,
    inputs,
    puzzleBlankIds,
    verifiedPuzzles,
  ]);

  readyMicropuzzleRef.current = readyMicropuzzle;

  useEffect(() => {
    for (const puzzleIdx of verifiedPuzzles) {
      const ids = puzzleBlankIds[puzzleIdx];
      if (!ids?.length) {
        continue;
      }

      const allFilled = ids.every(
        (id) => inputs[id] && inputs[id].trim() !== "",
      );

      if (!allFilled) {
        unverifyPuzzle(puzzleIdx);
        continue;
      }

      const inputString = ids.map((id) => inputs[id] || "").join("");
      const expectedHash = data[puzzleIdx]?.expectedHash;
      if (expectedHash) {
        const hash = Md5.hashStr(inputString);
        if (hash !== expectedHash) {
          unverifyPuzzle(puzzleIdx);
        }
      }
    }
  }, [inputs, puzzleBlankIds, verifiedPuzzles, data, unverifyPuzzle]);

  const readyMicropuzzleKey = readyMicropuzzle?.key;

  useEffect(() => {
    if (!readyMicropuzzleKey) {
      return;
    }

    const current = readyMicropuzzleRef.current;
    if (current?.key !== readyMicropuzzleKey) {
      return;
    }

    try {
      fetchExtractionInfo(current.puzzleIdx, current.micropuzzleData);
    } catch (error: unknown) {
      console.error(
        `Failed to fetch extraction info for puzzleIdx ${current.puzzleIdx}:`,
        error,
      );
    }
  }, [readyMicropuzzleKey, fetchExtractionInfo]);

  const exportState = () => {
    const exportObject: ExportedState = {
      puzzleId: id,
      inputs: inputs,
    };
    const exportString = JSON.stringify(exportObject);

    // Autocopy to clipboard
    navigator.clipboard
      .writeText(exportString)
      .then(() => {
        alert("Copied to clipboard.");
      })
      .catch((e: unknown) => {
        console.error(e);
        alert("Failed to copy to clipboard.");
      });
  };

  const importState = (overwriteAll = false) => {
    const userInput = prompt("Enter state:");

    if (!userInput) {
      return;
    }

    try {
      const importObject = JSON.parse(userInput) as ExportedState;
      if (importObject.puzzleId !== id) {
        alert("Error: Imported answers do not match the current puzzle.");
        return;
      }

      setInputs(() => {
        const newInputs: Record<string, string> = overwriteAll
          ? {}
          : { ...inputs };

        for (const key in importObject.inputs) {
          if (
            Object.hasOwn(importObject.inputs, key) &&
            typeof importObject.inputs[key] === "string" &&
            importObject.inputs[key].length > 0 &&
            (overwriteAll ||
              !(key in inputs) ||
              inputs[key] === undefined ||
              inputs[key].trim() === "")
          ) {
            newInputs[key] = importObject.inputs[key].charAt(0);
          }
        }

        return newInputs;
      });
    } catch {
      alert("Error: Invalid import data.");
    }
  };

  const importStateAll = () => {
    importState(true);
  };

  const importStateEmptyOnly = () => {
    importState(false);
  };

  const handleInput = (
    event: React.ChangeEvent<HTMLInputElement>,
    charId: string,
  ) => {
    const value = event.target.value;

    // Update the inputs object
    if (value && value.trim() !== "") {
      const upperValue = value.toUpperCase();
      setInputs((prev) => ({ ...prev, [charId]: upperValue }));

      // Force the input to show uppercase immediately
      event.target.value = upperValue;

      // If a non-space character was entered, navigate to next input
      setTimeout(() => {
        const inputs = Array.from(
          document.querySelectorAll('[data-blank-input="true"]'),
        ) as HTMLInputElement[];
        const currentIndex = inputs.indexOf(event.target);
        if (currentIndex >= 0 && currentIndex < inputs.length - 1) {
          const nextInput = inputs[currentIndex + 1];
          nextInput.focus();
          // Select all text if the next input has content
          if (nextInput.value) {
            nextInput.select();
          }
        }
      }, 0);
    } else {
      setInputs((prev) => {
        if (!(charId in prev)) return prev;
        const { [charId]: _removed, ...rest } = prev;
        return rest;
      });
    }
  };

  const handleFocus = (event: React.FocusEvent<HTMLInputElement>) => {
    // When focusing on an input with existing text, select it
    if (event.target.value) {
      event.target.select();
    }
  };

  const handleKeyDown = (
    event: React.KeyboardEvent<HTMLInputElement>,
    _: string,
  ) => {
    // We only care about the Backspace key
    if (event.key !== "Backspace") {
      return;
    }

    const currentInput = event.currentTarget;

    // Check if the current input is empty
    if (currentInput.value === "") {
      // Prevent the default backspace behavior (like browser navigation)
      event.preventDefault();

      // Get all the inputs on the page in order
      const inputs = Array.from(
        document.querySelectorAll('[data-blank-input="true"]'),
      ) as HTMLInputElement[];
      const currentIndex = inputs.indexOf(currentInput);

      // Check if there is a previous input
      if (currentIndex > 0) {
        const prevInput = inputs[currentIndex - 1];

        // Get the charId of the *previous* input
        // (We will add 'data-char-id' to the input in step 5)
        const prevCharId = prevInput.getAttribute("data-char-id");

        if (prevCharId) {
          // Clear the value of the previous input in our React state
          setInputs((prev) => {
            if (!(prevCharId in prev)) return prev;
            const { [prevCharId]: _removed, ...rest } = prev;
            return rest;
          });
        }

        // Move the cursor to the previous input
        prevInput.focus();
      }
    }
  };

  return (
    <div>
      <div className="flex gap-2">
        <Button onClick={importStateAll}>Import</Button>
        <Button onClick={importStateEmptyOnly}>
          Import (Overwrite only empty cells)
        </Button>
        <Button onClick={exportState}>Export</Button>
      </div>
      <div className={`sr-only ${NO_COPY_CLASS}`} aria-live="polite">
        {overallPuzzleAria}
      </div>

      <br />

      {data.map((puzzle, puzzleIdx) => (
        <div
          key={puzzleIdx}
          style={{
            width: "100%",
            marginTop: 24,
            padding: verifiedPuzzles.has(puzzleIdx) ? 10 : 15,
            border: verifiedPuzzles.has(puzzleIdx) ? "6px solid" : "1px solid",
            borderColor: verifiedPuzzles.has(puzzleIdx) ? "#00CC00" : "black",
            display: "flex",
            flexDirection: "column",
          }}
        >
          <h2 className={`sr-only ${NO_COPY_CLASS}`} aria-live="polite">
            {ariaLabels[puzzleIdx]}
          </h2>
          <div
            style={{
              display: "flex",
              flexDirection: "row",
            }}
          >
            <div
              style={{
                minWidth: 0,
                flex: 1,
              }}
            >
              {puzzle.title &&
                (!puzzle.title.given || puzzle.title.data.length > 0) && (
                  <div style={{ fontSize: 24, display: "flex" }}>
                    <FieldComponent
                      fields={puzzle.title}
                      extractionInfo={
                        extractionInfo[puzzleIdx] === undefined
                          ? undefined
                          : extractionInfo[puzzleIdx][0]
                      }
                      inputHandler={handleInput}
                      focusHandler={handleFocus}
                      keyDownHandler={handleKeyDown}
                      inputs={inputs}
                    />
                  </div>
                )}
            </div>
            <div
              style={{
                marginLeft: 20,
                marginTop: 8,
                width: 40,
                textAlign: "right",
              }}
            >
              {(verifiedPuzzles.has(puzzleIdx)
                ? parseEmoji("✅")
                : pendingChecks.has(puzzleIdx)
                  ? parseEmoji("⏳")
                  : parseEmoji("❌")
              ).map((e) => (
                <img
                  key={e.text}
                  src={e.url}
                  alt={e.text}
                  className={cn(NO_COPY_CLASS, "inline-block align-middle")}
                />
              ))}
            </div>
          </div>
          <hr style={{ width: "100%" }} />

          <div style={{ display: "flex" }}>
            <div
              style={{
                width: 300,
                height: 300,
                marginRight: 16,
                flexShrink: 0,
              }}
            >
              <img
                style={{
                  objectFit: "contain",
                  objectPosition: "0% 0%",
                  width: "100%",
                  height: "100%",
                }}
                src={puzzle.imageSrc}
                alt={puzzle.alt}
              />
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>
              {puzzle.fields.map((fields, i) => (
                <div key={i} style={{ fontSize: 24, display: "flex" }}>
                  <span style={{ marginRight: "10px" }}>
                    {circledNumbers[i]}:
                  </span>
                  <FieldComponent
                    fields={fields}
                    extractionInfo={
                      extractionInfo[puzzleIdx] === undefined
                        ? undefined
                        : extractionInfo[puzzleIdx][i + 1]
                    }
                    inputHandler={handleInput}
                    focusHandler={handleFocus}
                    keyDownHandler={handleKeyDown}
                    inputs={inputs}
                  />
                </div>
              ))}
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

export default PuzzleComponent;
