import {
  type RawField,
  type RawLayerPuzzle,
  type LayerPuzzle,
  type GivenBlank,
  type LinkedBlank,
  type UnlinkedBlank,
  type Blank,
  type Field,
  type Micropuzzle,
  type RawBlank,
} from "./types.js";

function createGivenBlank(blank: string): GivenBlank {
  return {
    given: true,
    linked: false,
    id: null,
    displayedId: null,
    displayedChar: blank,
  };
}

function createLinkedItem(id: string, displayedId: number): LinkedBlank {
  return {
    given: false,
    linked: true,
    id: id,
    displayedId: displayedId,
    displayedChar: null,
  };
}

function createUnlinkedItem(id: string): UnlinkedBlank {
  return {
    given: false,
    linked: false,
    id: id,
    displayedId: null,
    displayedChar: null,
  };
}

export function processData(puzzle: RawLayerPuzzle): LayerPuzzle {
  const parsedMicropuzzles: Micropuzzle[] = [];
  const rawIdToId: Record<number, string> = {};
  const idToDisplayedId: Record<string, number> = {};

  let displayedIdCounter = 1;

  const processBlank = (blank: RawBlank, id: string): Blank => {
    if (typeof blank === "string") {
      return createGivenBlank(blank);
    } else if (blank > 0) {
      if (blank in rawIdToId) {
        // Reuse old id and displayId
        id = rawIdToId[blank];
        const displayedId = idToDisplayedId[id];

        return createLinkedItem(id, displayedId);
      } else {
        // New linked id
        const displayedId = displayedIdCounter++;

        rawIdToId[blank] = id;
        idToDisplayedId[id] = displayedId;

        return createLinkedItem(id, displayedId);
      }
    } else {
      return createUnlinkedItem(id);
    }
  };

  const processField = (
    field: RawField,
    puzzleId: number,
    fieldId: number,
  ): Field => {
    if (typeof field === "string") {
      return { given: true, data: field };
    }

    let blankIndex = 1;

    const fieldData = field.map((item) => {
      const id = `p${puzzleId}f${fieldId}b${blankIndex++}`;
      return processBlank(item, id);
    });

    return { given: false, data: fieldData };
  };

  for (let puzzleIdx = 0; puzzleIdx < puzzle.length; puzzleIdx++) {
    const micropuzzle = puzzle[puzzleIdx];

    const processedTitle = processField(micropuzzle.title, puzzleIdx, 0);
    const processedFields = micropuzzle.fields.map((field, i) =>
      processField(field, puzzleIdx, i + 1),
    );

    parsedMicropuzzles.push({
      imageSrc: micropuzzle.imageSrc,
      alt: micropuzzle.alt,
      title: processedTitle,
      fields: processedFields,
      expectedHash: micropuzzle.expectedHash,
    });
  }

  return parsedMicropuzzles;
}
